{
  "actions": [
    {
      "action": "Track completion separately for every requested item",
      "mechanism": "Calculate outstanding quantities from linked physical receipts, keeping supplier-confirmed quantities separate from delivered quantities.",
      "implementation": "Add request-line IDs, requested quantity, confirmed quantity, received quantity, outstanding quantity, and item status to the existing spreadsheet or tracker.",
      "check": "Request ten units; record confirmation of ten and deliveries of three and four. Show seven received, three outstanding.",
      "risk": "Inconsistent quantity units can produce misleading balances."
    },
    {
      "action": "Give substitutions an independent named decision owner",
      "mechanism": "A substitution remains unresolved until someone other than its requester records an explicit decision and rationale.",
      "implementation": "Record original and replacement item IDs, quantity equivalence, requester, named approver, decision, rationale, and timestamp. Block requester approval.",
      "check": "Attempt self-approval and verify rejection. Confirm another studio member can approve with rationale and preserve the original request.",
      "risk": "Absent approvers can delay resolution; name an eligible backup."
    },
    {
      "action": "Prevent duplicate receipts from increasing delivered quantities",
      "mechanism": "Stable receipt identifiers make repeated entry harmless; similarity checks flag duplicates entered under different identifiers.",
      "implementation": "Key receipt lines by supplier, receipt number, and line number. Block repeated keys; flag matching item, quantity, and delivery-date combinations for review.",
      "check": "Import the same receipt twice: totals must remain unchanged. A similar legitimate second delivery must be releasable after review.",
      "risk": "Similarity alone cannot reliably distinguish duplicates from repeat deliveries."
    },
    {
      "action": "Separate excess delivery from request fulfillment",
      "mechanism": "Keep physical quantities intact while identifying overages as unresolved exceptions rather than silently expanding the request.",
      "implementation": "Show excess quantity separately, cap fulfilled quantity at the requested amount, and assign an existing teammate to record disposition of excess stock.",
      "check": "Receive twelve against ten requested: show twelve received, ten fulfilled, two excess, zero outstanding, and an open exception.",
      "risk": "Automatic closure would hide unresolved excess stock."
    },
    {
      "action": "Route ambiguous receipts through a matching inbox",
      "mechanism": "Receipts without a reliable request-line match remain visible without prematurely satisfying any purchase request.",
      "implementation": "Match using request reference and item ID. Send ambiguous matches or unapproved replacement items to an inbox with a named resolver.",
      "check": "Create two open requests for the same item. An unreferenced receipt must not automatically complete either request.",
      "risk": "Unresolved matching work can make genuine deliveries appear outstanding."
    },
    {
      "action": "Show the next action alongside completion",
      "mechanism": "Separate quantity completion from unresolved decisions so fully delivered requests can still visibly need attention.",
      "implementation": "Create a shared view showing outstanding lines, pending substitutions, unmatched receipts, overages, named action owners, and review dates. Close only when quantities and exceptions are resolved.",
      "check": "A quantity-complete request with an unresolved overage stays open; a partial request identifies its outstanding item and next action.",
      "risk": "Unmaintained owners and dates create a stale queue."
    },
    {
      "action": "Correct receipt mistakes without deleting history",
      "mechanism": "Linked reversals and replacement entries preserve evidence while recalculating item balances and reopening affected requests.",
      "implementation": "Protect posted receipt rows. Record corrections as signed quantity adjustments linked to the original entry, with author, timestamp, and reason.",
      "check": "Correct a ten-unit receipt to six after closure. Verify six net received, four outstanding, reopened status, and retained history.",
      "risk": "Unlinked adjustments can obscure which receipt was corrected."
    }
  ],
  "abstention_reason": ""
}
